import sqlite3
def run_sql(query, limit=20):
    con = sqlite3.connect(f"file:{DB}?mode=ro", uri=True)
    try:
        rows = con.execute(query).fetchall()
    except Exception as e:
        print("SQL error:", e); return
    finally:
        con.close()
    print(f"{len(rows)} rows"); [print(r) for r in rows[:limit]]

