import sqlite3
def sample_rows(table, n=3):
    con = sqlite3.connect(f"file:{DB}?mode=ro", uri=True)
    try:
        cur = con.execute(f'SELECT * FROM "{table}" LIMIT ?', (n,))
        print([d[0] for d in cur.description]); [print(r) for r in cur.fetchall()]
    except Exception as e:
        print("error:", e)
    finally:
        con.close()

